-- Erratas de copia en enunciados y opciones (revisión 2026-10).
-- 131 campos de 107 preguntas (grupos A, B y C: solo espacios; grupo D: guion, letra o tilde)
-- y 4 explicaciones que repetían el mismo texto (con copia en el historial).
-- Guarda md5 por campo y por explicación; si no salen 131 + 4 y historial +4, ROLLBACK de todo.
BEGIN;
CREATE TEMP TABLE fx (id int, campo text, antes_md5 text, despues text) ON COMMIT DROP;
CREATE TEMP TABLE fe (id int, antes_md5 text, despues text) ON COMMIT DROP;
CREATE TEMP TABLE h0 ON COMMIT DROP AS SELECT count(*) n FROM explicaciones_historial;
SET LOCAL mir.motivo = 'Erratas de copia 2026-10';
DO $$ DECLARE n int := 0; k int; ne int; h int; BEGIN
  UPDATE preguntas p SET pregunta = fx.despues FROM fx WHERE fx.campo = 'pregunta' AND p.id = fx.id AND md5(p.pregunta) = fx.antes_md5;
  GET DIAGNOSTICS k = ROW_COUNT; n := n + k;
  UPDATE preguntas p SET opcion_a = fx.despues FROM fx WHERE fx.campo = 'opcion_a' AND p.id = fx.id AND md5(p.opcion_a) = fx.antes_md5;
  GET DIAGNOSTICS k = ROW_COUNT; n := n + k;
  UPDATE preguntas p SET opcion_b = fx.despues FROM fx WHERE fx.campo = 'opcion_b' AND p.id = fx.id AND md5(p.opcion_b) = fx.antes_md5;
  GET DIAGNOSTICS k = ROW_COUNT; n := n + k;
  UPDATE preguntas p SET opcion_c = fx.despues FROM fx WHERE fx.campo = 'opcion_c' AND p.id = fx.id AND md5(p.opcion_c) = fx.antes_md5;
  GET DIAGNOSTICS k = ROW_COUNT; n := n + k;
  UPDATE preguntas p SET opcion_d = fx.despues FROM fx WHERE fx.campo = 'opcion_d' AND p.id = fx.id AND md5(p.opcion_d) = fx.antes_md5;
  GET DIAGNOSTICS k = ROW_COUNT; n := n + k;
  UPDATE preguntas p SET opcion_e = fx.despues FROM fx WHERE fx.campo = 'opcion_e' AND p.id = fx.id AND md5(p.opcion_e) = fx.antes_md5;
  GET DIAGNOSTICS k = ROW_COUNT; n := n + k;
  UPDATE preguntas p SET explicacion = fe.despues FROM fe WHERE p.id = fe.id AND md5(p.explicacion) = fe.antes_md5;
  GET DIAGNOSTICS ne = ROW_COUNT;
  SELECT (SELECT count(*) FROM explicaciones_historial) - h0.n INTO h FROM h0;
  IF n <> 131 OR ne <> 4 OR h <> 4 THEN
    RAISE EXCEPTION 'campos % (esperado 131), explicaciones % (esperado 4), historial +% (esperado 4): ROLLBACK de todo', n, ne, h;
  END IF;
  RAISE NOTICE 'campos %, explicaciones %, historial +%', n, ne, h;
END $$;
COMMIT;
